import{_ as a,o,c as t,a2 as l}from"./chunks/framework.BZO4qERu.js";const k=JSON.parse('{"title":"Slack","description":"","frontmatter":{},"headers":[],"relativePath":"zh/integrations/channels/slack.md","filePath":"zh/integrations/channels/slack.md","lastUpdated":1790952322000}'),r={name:"zh/integrations/channels/slack.md"};function i(c,e,s,n,d,p){return o(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="slack" tabindex="-1">Slack <a class="header-anchor" href="#slack" aria-label="Permalink to &quot;Slack&quot;">​</a></h1><p>把 Memoh Bot 接到 Slack：收 DM、进频道、跟 thread、读附件、发文件、流式回复。</p><h2 id="前提条件" tabindex="-1">前提条件 <a class="header-anchor" href="#前提条件" aria-label="Permalink to &quot;前提条件&quot;">​</a></h2><ul><li>一个可以安装 app 的 Slack workspace，并能访问 <a href="https://api.slack.com/apps" target="_blank" rel="noreferrer">Slack API 控制台</a>。</li><li>一个 Memoh Bot；渠道在它的 <strong>平台</strong> 标签页里配置。</li></ul><h2 id="步骤" tabindex="-1">步骤 <a class="header-anchor" href="#步骤" aria-label="Permalink to &quot;步骤&quot;">​</a></h2><h3 id="_1-在-slack-api-控制台创建-app" tabindex="-1">1. 在 Slack API 控制台创建 app <a class="header-anchor" href="#_1-在-slack-api-控制台创建-app" aria-label="Permalink to &quot;1. 在 Slack API 控制台创建 app&quot;">​</a></h3><ol><li>打开 <a href="https://api.slack.com/apps" target="_blank" rel="noreferrer">Slack API 控制台</a>，点 <strong>Create New App</strong>。</li><li>选择要安装 Bot 的 workspace。</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>保持 app 设置页开着，第 2 到 5 步都在这里完成。</p></div><h3 id="_2-在-slack-api-控制台开启-socket-mode" tabindex="-1">2. 在 Slack API 控制台开启 Socket Mode <a class="header-anchor" href="#_2-在-slack-api-控制台开启-socket-mode" aria-label="Permalink to &quot;2. 在 Slack API 控制台开启 Socket Mode&quot;">​</a></h3><p>Memoh 的 Slack 适配走 Socket Mode，所以除 Bot token 外还需要一个 app-level token。</p><ol><li>在 <strong>Basic Information</strong> 里开启 <strong>Socket Mode</strong>。</li><li>创建 <strong>App-Level Token</strong>，scope 勾 <code>connections:write</code>。</li><li>复制生成的 token，以 <code>xapp-</code> 开头。</li></ol><h3 id="_3-在-slack-api-控制台加-bot-token-scopes" tabindex="-1">3. 在 Slack API 控制台加 Bot Token Scopes <a class="header-anchor" href="#_3-在-slack-api-控制台加-bot-token-scopes" aria-label="Permalink to &quot;3. 在 Slack API 控制台加 Bot Token Scopes&quot;">​</a></h3><p>在 <strong>OAuth &amp; Permissions</strong> 里加上 Slack 适配需要的 scope：</p><ul><li><code>app_mentions:read</code>：接收频道里对 Bot 的 @</li><li><code>channels:history</code>：读公开频道消息</li><li><code>groups:history</code>：读私有频道消息</li><li><code>im:history</code>：读 DM</li><li><code>mpim:history</code>：读多人 DM</li><li><code>chat:write</code>：发送回复和 thread 消息</li><li><code>files:read</code>：读上传的文件和图片</li><li><code>files:write</code>：发出文件</li><li><code>reactions:write</code>：添加/移除 reaction</li></ul><p>想让会话名称、元数据在 Memoh 里显示得更全，建议再加：</p><ul><li><code>channels:read</code></li><li><code>groups:read</code></li><li><code>im:read</code></li><li><code>mpim:read</code></li></ul><h3 id="_4-在-slack-api-控制台订阅事件" tabindex="-1">4. 在 Slack API 控制台订阅事件 <a class="header-anchor" href="#_4-在-slack-api-控制台订阅事件" aria-label="Permalink to &quot;4. 在 Slack API 控制台订阅事件&quot;">​</a></h3><p>在 <strong>Event Subscriptions</strong> 里开启 bot events，加上 Slack 适配处理的入站事件：</p><ul><li><code>app_mention</code></li><li><code>message.channels</code></li><li><code>message.groups</code></li><li><code>message.im</code></li><li><code>message.mpim</code></li></ul><h3 id="_5-在-slack-api-控制台把-app-装进-workspace" tabindex="-1">5. 在 Slack API 控制台把 app 装进 workspace <a class="header-anchor" href="#_5-在-slack-api-控制台把-app-装进-workspace" aria-label="Permalink to &quot;5. 在 Slack API 控制台把 app 装进 workspace&quot;">​</a></h3><ol><li>在 <strong>OAuth &amp; Permissions</strong> 点 <strong>Install to Workspace</strong>。</li><li>确认权限页并授权。</li><li>复制 <strong>Bot User OAuth Token</strong>，以 <code>xoxb-</code> 开头。</li></ol><h3 id="_6-在-memoh-添加-slack-渠道" tabindex="-1">6. 在 Memoh 添加 Slack 渠道 <a class="header-anchor" href="#_6-在-memoh-添加-slack-渠道" aria-label="Permalink to &quot;6. 在 Memoh 添加 Slack 渠道&quot;">​</a></h3><ol><li>打开 Bot 详情页，进入 <strong>平台</strong> 标签页。</li><li>点 <strong>Add Channel</strong>，选 <strong>Slack</strong>。</li><li>填写： <ul><li><strong>Bot Token</strong>：<code>xoxb-</code> 开头的 token</li><li><strong>App-Level Token</strong>：<code>xapp-</code> 开头的 token</li></ul></li><li>点 <strong>Save and Enable</strong>。</li></ol><h3 id="_7-在-slack-把-bot-加进对话" tabindex="-1">7. 在 Slack 把 Bot 加进对话 <a class="header-anchor" href="#_7-在-slack-把-bot-加进对话" aria-label="Permalink to &quot;7. 在 Slack 把 Bot 加进对话&quot;">​</a></h3><p>渠道启用后，还要让这个 Slack app 出现在你想用它的对话里：</p><ul><li>DM：和该 app 开对话并发一条消息。</li><li>公开频道：把 Bot 邀请进频道。</li><li>私有频道：装好后显式邀请进频道。</li></ul><h2 id="凭据" tabindex="-1">凭据 <a class="header-anchor" href="#凭据" aria-label="Permalink to &quot;凭据&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td><strong>Bot Token</strong></td><td>装进 workspace 后复制的 <strong>Bot User OAuth Token</strong>（<code>xoxb-</code> 开头）。</td></tr><tr><td><strong>App-Level Token</strong></td><td>为 Socket Mode 创建、带 <code>connections:write</code> scope 的 token（<code>xapp-</code> 开头）。</td></tr></tbody></table><p>两个 token 必须来自同一个 Slack app、同一个 workspace。</p><h2 id="验证" tabindex="-1">验证 <a class="header-anchor" href="#验证" aria-label="Permalink to &quot;验证&quot;">​</a></h2><p>把 Bot 邀请进一个频道并 @它发送 <code>/help</code>，或在 DM 里发 <code>/help</code>。Bot 回复命令列表即说明渠道已生效。</p><h2 id="群聊" tabindex="-1">群聊 <a class="header-anchor" href="#群聊" aria-label="Permalink to &quot;群聊&quot;">​</a></h2><p>Slack 频道即群聊场景。把 Bot 邀请进公开或私有频道，@它即可对话；回复可以在 thread 里继续，Slack 也是唯一支持 thread 的渠道。</p><h2 id="停用与更换凭据" tabindex="-1">停用与更换凭据 <a class="header-anchor" href="#停用与更换凭据" aria-label="Permalink to &quot;停用与更换凭据&quot;">​</a></h2><p>在 Bot 的 <strong>平台</strong> 标签页可以随时停用或移除该渠道。更换凭据时，更新 <strong>Bot Token</strong> 与 <strong>App-Level Token</strong> 字段并保存即可。</p><h2 id="faq" tabindex="-1">常见问题 <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;常见问题 {#faq}&quot;">​</a></h2><h3 id="why-two-tokens" tabindex="-1">为什么要填两个 token？ <a class="header-anchor" href="#why-two-tokens" aria-label="Permalink to &quot;为什么要填两个 token？ {#why-two-tokens}&quot;">​</a></h3><p>Memoh 的 Slack 适配走 Socket Mode：除 <code>xoxb-</code> 开头的 Bot token 外，还需要 <code>xapp-</code> 开头的 app-level token，且两者必须来自同一个 Slack app 和 workspace。</p><h3 id="cannot-read-files" tabindex="-1">Bot 能发消息，但读不到上传的图片或文件 <a class="header-anchor" href="#cannot-read-files" aria-label="Permalink to &quot;Bot 能发消息，但读不到上传的图片或文件 {#cannot-read-files}&quot;">​</a></h3><p>检查 <code>files:read</code> scope 是否已开启。</p><h3 id="no-incoming-messages" tabindex="-1">连上了，但收不到任何入站消息 <a class="header-anchor" href="#no-incoming-messages" aria-label="Permalink to &quot;连上了，但收不到任何入站消息 {#no-incoming-messages}&quot;">​</a></h3><p>重新核对 <strong>Event Subscriptions</strong> 里的 bot events，以及配套的 <code>history</code> 类 scope。</p>',42)])])}const m=a(r,[["render",i]]);export{k as __pageData,m as default};
